import { Group, PlaneGeometry, MeshBasicNodeMaterial, TextureLoader } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Geometry: plane with aspect ratio from atlas source (512x320)
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Material placeholder – will be replaced by loaded texture
  const material = new MeshBasicNodeMaterial({
    color: config.colors?.surface || '#0b0b10',
  });

  const mesh = new Mesh(geometry, material);
  // Position from config.scenePosition is applied later, but we set local position from spec
  mesh.position.set(0, -0.3, 0);
  // Rotation and scale defaults – spec says (0,0,0) rotation, (1,1,1) scale
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  group.add(mesh);

  // Load texture and apply
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    material.map = texture;
    material.needsUpdate = true;
  });

  // No interactions – empty handlers
  group.userData.handlers = {};

  // Cleanup: dispose resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // No GSAP timelines to kill
  };

  return group;
}
